"""Exact branch coefficients and uncontracted nonnegative sign-routing networks."""

from __future__ import annotations

from dataclasses import dataclass

from .instance import Instance
from .rational import RawPair, validate_pair

__all__ = (
    "SignRoutedNetwork",
    "SignRoutingCoefficients",
    "branch_coefficients",
    "build_sign_routed_network",
    "recover_objective",
)


def _require_int(value: object, name: str) -> None:
    """Reject non-integer objects without invoking their conversion hooks."""
    if type(value) is not int:
        raise ValueError(f"{name} must be an exact built-in int")


@dataclass(frozen=True, slots=True)
class SignRoutingCoefficients:
    """Literal coefficients of a cut term, vertex terms, and a separate constant."""

    a: int
    gamma: tuple[int, ...]
    constant: int

    def __post_init__(self) -> None:
        _require_int(self.a, "a")
        if self.a < 0:
            raise ValueError("a must be nonnegative")
        if type(self.gamma) is not tuple:
            raise ValueError("gamma must be an exact tuple")
        for coefficient in self.gamma:
            _require_int(coefficient, "gamma entry")
        _require_int(self.constant, "constant")


@dataclass(frozen=True, slots=True)
class SignRoutedNetwork:
    """Immutable original capacity arcs; construction alone asserts no provenance."""

    vertex_count: int
    arcs: tuple[tuple[int, int, int], ...]
    negative_shift: int
    constant: int

    def __post_init__(self) -> None:
        _require_int(self.vertex_count, "vertex_count")
        if self.vertex_count < 1:
            raise ValueError("vertex_count must be positive")
        if type(self.arcs) is not tuple:
            raise ValueError("arcs must be an exact tuple")
        node_count = self.vertex_count + 2
        for arc in self.arcs:
            if type(arc) is not tuple or len(arc) != 3:
                raise ValueError("each arc must be an exact three-element tuple")
            tail, head, capacity = arc
            _require_int(tail, "arc tail")
            _require_int(head, "arc head")
            _require_int(capacity, "arc capacity")
            if not 0 <= tail < node_count or not 0 <= head < node_count:
                raise ValueError("arc endpoint is outside the network")
            if tail == head:
                raise ValueError("self-loops are not valid network records")
            if capacity < 0:
                raise ValueError("arc capacity must be nonnegative")
        _require_int(self.negative_shift, "negative_shift")
        if self.negative_shift < 0:
            raise ValueError("negative_shift must be nonnegative")
        _require_int(self.constant, "constant")

    @property
    def node_count(self) -> int:
        """Return the original vertex count plus the two fixed terminals."""
        return self.vertex_count + 2

    @property
    def source(self) -> int:
        """Return the fixed source index."""
        return self.vertex_count

    @property
    def sink(self) -> int:
        """Return the fixed sink index."""
        return self.vertex_count + 1


def branch_coefficients(
    instance: Instance,
    branch: int,
    parameter: RawPair,
) -> SignRoutingCoefficients:
    """Expand the selected raw branch residual without checking shore feasibility."""
    if type(instance) is not Instance:
        raise ValueError("instance must be an exact production Instance")
    _require_int(branch, "branch")
    if branch not in (0, 1, 2, 3):
        raise ValueError("branch must be 0, 1, 2, or 3")
    validate_pair(parameter)

    numerator, denominator = parameter
    degrees = instance.d_q
    if branch < 2:
        combined = numerator + denominator
        gamma = tuple(
            combined * instance.f[vertex] - numerator * degrees[vertex]
            for vertex in range(instance.n)
        )
        constant = -combined if branch == 0 else -2 * denominator
    else:
        gamma = tuple(
            -denominator * degrees[vertex] - numerator * instance.f[vertex]
            for vertex in range(instance.n)
        )
        constant = numerator if branch == 2 else -2 * denominator
    return SignRoutingCoefficients(denominator, gamma, constant)


def build_sign_routed_network(
    instance: Instance,
    coefficients: SignRoutingCoefficients,
) -> SignRoutedNetwork:
    """Emit support pairs then vertex-order spoke pairs, retaining every zero arc."""
    if type(instance) is not Instance:
        raise ValueError("instance must be an exact production Instance")
    if type(coefficients) is not SignRoutingCoefficients:
        raise ValueError("coefficients must be an exact SignRoutingCoefficients")
    if len(coefficients.gamma) != instance.n:
        raise ValueError("gamma length must equal the original vertex count")

    source = instance.n
    sink = source + 1
    arcs: list[tuple[int, int, int]] = []
    for u, v, multiplicity in instance.edges:
        capacity = coefficients.a * multiplicity
        arcs.append((u, v, capacity))
        arcs.append((v, u, capacity))

    negative_shift = 0
    for vertex, coefficient in enumerate(coefficients.gamma):
        if coefficient >= 0:
            arcs.append((vertex, sink, coefficient))
            arcs.append((sink, vertex, coefficient))
        else:
            capacity = -coefficient
            arcs.append((source, vertex, capacity))
            arcs.append((vertex, source, capacity))
            negative_shift += capacity

    return SignRoutedNetwork(instance.n, tuple(arcs), negative_shift, coefficients.constant)


def recover_objective(network: SignRoutedNetwork, cut_value: int) -> int:
    """Remove the routing shift and add the constant; assert no cut or minimum."""
    if type(network) is not SignRoutedNetwork:
        raise ValueError("network must be an exact SignRoutedNetwork")
    _require_int(cut_value, "cut_value")
    if cut_value < 0:
        raise ValueError("cut_value must be nonnegative")
    return cut_value - network.negative_shift + network.constant

exactfrac/solve.py.source:
"""StrongCompactMSPD global composition and original compact witness reconstruction.

Implement alg:global under DESIGN 4.12. The selected closed branch solver owns
branch optimality. This wrapper binds each original endpoint to its branch root,
compares raw witness-attaining values, and retains the first strict maximum.
Diagnostics are separate; no record here is an independent optimality certificate.
"""

from __future__ import annotations

from dataclasses import dataclass

from .branch import (
    AcceleratedBranchStats,
    BranchResult,
    StandardBranchStats,
    solve_branch_accelerated,
    solve_branch_standard,
)
from .instance import Instance
from .oracle import BranchOracleContext
from .rational import compare_pairs
from .witness import ExactValue, Witness, shore_b_q, shore_d_q, shore_f, witness_value

__all__ = ("SolveResult", "SolveStats", "solve")


def _selected_stats_type(branch_solver: str) -> type[StandardBranchStats | AcceleratedBranchStats]:
    """Validate the explicit public selection without coercion or graph access."""
    if type(branch_solver) is not str or branch_solver not in ("Standard", "Accelerated"):
        raise ValueError('branch_solver must be an exact str: "Standard" or "Accelerated"')
    return StandardBranchStats if branch_solver == "Standard" else AcceleratedBranchStats


@dataclass(frozen=True, slots=True)
class SolveResult:
    """Raw mathematical result; standalone construction checks record types only."""

    value: ExactValue
    witness: Witness | None

    def __post_init__(self) -> None:
        if type(self.value) is not ExactValue:
            raise ValueError("value must be an exact ExactValue")
        if self.witness is not None and type(self.witness) is not Witness:
            raise ValueError("witness must be an exact Witness or None")
        if self.witness is None and (self.value.N != 0 or self.value.D != 1):
            raise ValueError("an Empty result requires the literal raw value (0, 1)")


@dataclass(frozen=True, slots=True)
class SolveStats:
    """Retained closed diagnostics and provenance, not an execution certificate."""

    branch_solver: str
    branch_stats: tuple[StandardBranchStats | AcceleratedBranchStats, ...]
    attaining_candidate: str

    def __post_init__(self) -> None:
        selected_type = _selected_stats_type(self.branch_solver)
        if type(self.branch_stats) is not tuple:
            raise ValueError("branch_stats must be an exact tuple")
        for record in self.branch_stats:
            if type(record) is not selected_type:
                raise ValueError("every branch record must have the selected exact stats type")
        if type(self.attaining_candidate) is not str or self.attaining_candidate not in (
            "Empty", "Baseline", "L0", "L1", "H0", "H1", "H2",
        ):
            raise ValueError("attaining_candidate must be an exact recognized str")


def _baseline_shore(instance: Instance, degrees: tuple[int, ...]) -> int:
    """Refine lem:empty by category priority, then increasing vertex index."""
    for vertex, capacity in enumerate(instance.f):
        if not capacity & 1:
            return 1 << vertex
    for vertex, capacity in enumerate(instance.f):
        if capacity >= 3:
            return 1 << vertex
    for vertex, capacity in enumerate(instance.f):
        if capacity == 1 and degrees[vertex] >= 2:
            return 1 << vertex

    # The remaining source case is a unit matching with at least two edges.
    for vertex, capacity in enumerate(instance.f):
        if capacity != 1 or degrees[vertex] != 1:
            raise RuntimeError("the baseline's remaining case is not a unit matching")
    if instance.m < 2:
        raise RuntimeError("the matching baseline requires at least two support edges")
    covered = 0
    for left, right, multiplicity in instance.edges:
        endpoints = (1 << left) | (1 << right)
        if multiplicity != 1 or covered & endpoints:
            raise RuntimeError("the matching baseline requires disjoint unit edges")
        covered |= endpoints
    if covered != (1 << instance.n) - 1:
        raise RuntimeError("the matching baseline must cover the original vertex universe")
    return (1 << instance.edges[0][0]) | (1 << instance.edges[1][0])


def _all_boundary(instance: Instance, U: int, omit_one: bool) -> tuple[int, ...]:
    """Take all crossing copies, optionally omitting one from the first edge."""
    counts = [0] * instance.m
    remaining = int(omit_one)
    for edge_ref, (left, right, multiplicity) in enumerate(instance.edges):
        if bool(U & (1 << left)) != bool(U & (1 << right)):
            counts[edge_ref] = multiplicity - remaining
            remaining = 0
    if remaining:
        raise RuntimeError("omitting one copy requires an actual crossing edge")
    return tuple(counts)


def _first_copies(instance: Instance, U: int, total: int) -> tuple[int, ...]:
    """Take one or two copies by a support scan, never a multiplicity-sized loop."""
    counts = [0] * instance.m
    remaining = total
    for edge_ref, (left, right, multiplicity) in enumerate(instance.edges):
        if bool(U & (1 << left)) != bool(U & (1 << right)):
            taken = min(multiplicity, remaining)
            counts[edge_ref] = taken
            remaining -= taken
    if remaining:
        raise RuntimeError("the endpoint requires more incident copies than the scan found")
    return tuple(counts)


def _evaluate(instance: Instance, witness: Witness) -> ExactValue:
    """Accept only the normally returned closed evaluator record; exceptions pass through."""
    value = witness_value(instance, witness)
    if type(value) is not ExactValue:
        raise RuntimeError("witness_value returned an unexpected record type")
    return value


def _baseline(instance: Instance, degrees: tuple[int, ...]) -> tuple[ExactValue, Witness]:
    """Upgrade the feasibility shore using lem:unit, then retain its actual raw value."""
    U = _baseline_shore(instance, degrees)
    s = shore_f(instance, U)
    b = shore_b_q(instance, U)
    odd = (s + b) & 1
    if (odd and s + b < 3) or (not odd and (b < 1 or s + b < 4)):
        raise RuntimeError("the baseline shore violates the unit-witness prerequisites")
    witness = Witness(U, _all_boundary(instance, U, not odd))
    value = _evaluate(instance, witness)
    if compare_pairs((value.N, value.D), (1, 1)) < 0:
        raise RuntimeError("the constructive baseline has value below one")
    return value, witness


def _endpoint(instance: Instance, branch: int, result: BranchResult) -> tuple[ExactValue, Witness]:
    """Reconstruct and numerically bind one original endpoint, not another optimum."""
    U = result.shore
    if not 0 < U < 1 << instance.n:
        raise RuntimeError("the branch shore is outside the original nonempty universe")
    s = shore_f(instance, U)
    b = shore_b_q(instance, U)
    d = shore_d_q(instance, U)
    if branch == 0:
        valid = (s + b) & 1 and s + b >= 3 and d + 1 - s > 0
        numerator, denominator = d + b, s + b - 1
    elif branch == 1:
        valid = not ((s + b) & 1) and b >= 1 and d > s and s + b >= 4
        numerator, denominator = d + b - 2, s + b - 2
    elif branch == 2:
        valid = (s & 1) and s >= 3
        numerator, denominator = d - b, s - 1
    else:
        valid = not (s & 1) and s >= 2 and b >= 1
        numerator, denominator = d - b + 2, s
    if not valid:
        raise RuntimeError("the branch shore violates its original endpoint domain")

    if branch < 2:
        counts = _all_boundary(instance, U, branch == 1)
    elif branch == 2:
        counts = (0,) * instance.m
    else:
        counts = _first_copies(instance, U, 1)
    witness = Witness(U, counts)
    value = _evaluate(instance, witness)
    if (numerator, denominator) != (value.N, value.D):
        raise RuntimeError("the evaluated raw endpoint differs from its literal source formula")
    A, B = result.root
    if branch < 2:
        bound = value.N > value.D and A * (value.N - value.D) == B * value.D
    else:
        bound = A * value.D == -B * value.N
    if not bound:
        raise RuntimeError("the branch root is not numerically bound to the reconstructed endpoint")
    return value, witness


def solve(instance: Instance, branch_solver: str) -> tuple[SolveResult, SolveStats]:
    """Return the global raw optimum and its original compact attaining witness.

    Validate public types before graph use. For Q >= 2, prepare once, retain a
    constructive baseline, traverse all four selected branches, then construct
    and compare direct H2 even when dominated. Keep only bounded candidate state
    beyond the prepared context and support-sized reconstruction workspace.
    No dependency exception is translated or used to return a partial result.
    """
    if type(instance) is not Instance:
        raise ValueError("instance must be an exact production Instance")
    selected_type = _selected_stats_type(branch_solver)
    if instance.Q == 1:
        return SolveResult(ExactValue(0, 1), None), SolveStats(branch_solver, (), "Empty")

    context = BranchOracleContext(instance)
    degrees = instance.d_q
    best_value, best_witness = _baseline(instance, degrees)
    origin = "Baseline"
    selected_solver = (
        solve_branch_standard if branch_solver == "Standard" else solve_branch_accelerated
    )
    records = []
    for branch in (0, 1, 2, 3):
        response = selected_solver(context, branch)
        if type(response) is not tuple or len(response) != 2:
            raise RuntimeError("a branch reply must be an exact two-element tuple")
        result, diagnostics = response
        if result is not None and type(result) is not BranchResult:
            raise RuntimeError("a branch reply has an unexpected result type")
        if type(diagnostics) is not selected_type:
            raise RuntimeError("a branch reply has the wrong selected diagnostics type")
        records.append(diagnostics)
        if result is None:
            continue
        value, witness = _endpoint(instance, branch, result)
        if compare_pairs((value.N, value.D), (best_value.N, best_value.D)) > 0:
            best_value, best_witness = value, witness
            origin = ("L0", "L1", "H0", "H1")[branch]

    for vertex, capacity in enumerate(instance.f):
        if capacity == 1 and degrees[vertex] >= 2:
            U = 1 << vertex
            witness = Witness(U, _first_copies(instance, U, 2))
            value = _evaluate(instance, witness)
            if (value.N, value.D) != (4, 2):
                raise RuntimeError("the direct H2 witness must attain the literal raw value (4, 2)")
            if compare_pairs((value.N, value.D), (best_value.N, best_value.D)) > 0:
                best_value, best_witness = value, witness
                origin = "H2"
            break
    return SolveResult(best_value, best_witness), SolveStats(branch_solver, tuple(records), origin)

exactfrac/witness.py.source:
"""Immutable witness records and exact witness evaluation for ExactFrac."""

from __future__ import annotations

from dataclasses import dataclass

from .instance import Instance
from .shore import validate_shore

__all__ = (
    "ExactValue",
    "Witness",
    "dense_y_to_sparse",
    "shore_b_q",
    "shore_d_q",
    "shore_e_q",
    "shore_f",
    "sparse_y_to_dense",
    "validate_witness",
    "witness_value",
)


@dataclass(frozen=True, slots=True)
class ExactValue:
    """One raw unreduced numerator-denominator record."""

    N: int
    D: int

    def __post_init__(self) -> None:
        if type(self.N) is not int:
            raise ValueError("N must be a built-in int")
        if type(self.D) is not int or self.D <= 0:
            raise ValueError("D must be a positive built-in int")


@dataclass(frozen=True, slots=True)
class Witness:
    """One immutable compact witness record ``(U, y)``."""

    U: int
    y: tuple[int, ...]

    def __post_init__(self) -> None:
        if type(self.U) is not int or self.U <= 0:
            raise ValueError("U must be a positive built-in int")
        if type(self.y) is not tuple:
            raise ValueError("y must be an exact tuple")
        for count in self.y:
            if type(count) is not int or count < 0:
                raise ValueError("every y coordinate must be a nonnegative built-in int")


def _require_instance(instance: object) -> Instance:
    if type(instance) is not Instance:
        raise ValueError("instance must be an exact production Instance")
    return instance


def _checked_instance_shore(instance: object, U: object) -> tuple[Instance, int]:
    checked_instance = _require_instance(instance)
    checked_shore = validate_shore(checked_instance.n, U)
    return checked_instance, checked_shore


def _crosses(U: int, left: int, right: int) -> bool:
    return bool(U & (1 << left)) != bool(U & (1 << right))


def _validate_dense(
    instance: Instance,
    U: int,
    y: object,
) -> tuple[int, ...]:
    if type(y) is not tuple or len(y) != instance.m:
        raise ValueError("dense y must be an exact tuple of length m")

    # Shape validation precedes every graph-dependent bound/boundary check.
    for count in y:
        if type(count) is not int or count < 0:
            raise ValueError("every dense y coordinate must be a nonnegative built-in int")

    for edge_ref, (left, right, multiplicity) in enumerate(instance.edges):
        count = y[edge_ref]
        if count > multiplicity:
            raise ValueError("dense y coordinate exceeds edge multiplicity")
        if not _crosses(U, left, right) and count != 0:
            raise ValueError("nonboundary dense y coordinates must be zero")

    return y


def shore_f(instance: Instance, U: int) -> int:
    """Return ``f(U)`` for one valid shore, including the empty shore."""

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    total = 0
    for vertex in range(checked_instance.n):
        if checked_shore & (1 << vertex):
            total += checked_instance.f[vertex]
    return total


def shore_e_q(instance: Instance, U: int) -> int:
    """Return the internal compact multiplicity ``e_q(U)``."""

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    total = 0
    for left, right, multiplicity in checked_instance.edges:
        if checked_shore & (1 << left) and checked_shore & (1 << right):
            total += multiplicity
    return total


def shore_b_q(instance: Instance, U: int) -> int:
    """Return the boundary compact multiplicity ``b_q(U)``."""

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    total = 0
    for left, right, multiplicity in checked_instance.edges:
        if _crosses(checked_shore, left, right):
            total += multiplicity
    return total


def shore_d_q(instance: Instance, U: int) -> int:
    """Return the multiplicity-weighted degree sum ``d_q(U)``."""

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    degrees = checked_instance.d_q
    total = 0
    for vertex in range(checked_instance.n):
        if checked_shore & (1 << vertex):
            total += degrees[vertex]
    return total


def dense_y_to_sparse(
    instance: Instance,
    U: int,
    y: tuple[int, ...],
) -> list[list[int]]:
    """Encode a valid boundary selection, not full admissibility or attainment.

    The empty and full shores accept only zero counts. An empty sparse result
    means zero selected copies, not an empty admissible family.
    """

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    checked_y = _validate_dense(checked_instance, checked_shore, y)
    return [
        [edge_ref, count]
        for edge_ref, count in enumerate(checked_y)
        if count > 0
    ]


def sparse_y_to_dense(
    instance: Instance,
    U: int,
    entries: list[list[int]],
) -> tuple[int, ...]:
    """Decode a valid boundary selection, not full admissibility or attainment.

    Records must already be canonical. No sorting, merging, or coercion is
    performed. Missing references decode to zero; [] is not an Empty result.
    """

    checked_instance, checked_shore = _checked_instance_shore(instance, U)
    if type(entries) is not list:
        raise ValueError("sparse y must be an exact list")

    previous = -1

    for record in entries:
        if type(record) is not list or len(record) != 2:
            raise ValueError("each sparse y record must be an exact two-entry list")

        edge_ref, count = record
        if type(edge_ref) is not int or type(count) is not int:
            raise ValueError("sparse y values must be built-in ints")
        if edge_ref < 0 or edge_ref >= checked_instance.m:
            raise ValueError("sparse y edge_ref is outside canonical edge order")
        if edge_ref <= previous:
            raise ValueError("sparse y edge_ref values must be strictly increasing")
        if count <= 0:
            raise ValueError("sparse y counts must be strictly positive")

        left, right, multiplicity = checked_instance.edges[edge_ref]
        if count > multiplicity:
            raise ValueError("sparse y count exceeds edge multiplicity")
        if not _crosses(checked_shore, left, right):
            raise ValueError("sparse y may reference only boundary edges")

        previous = edge_ref

    # Build the output only after every supplied record has been validated.
    dense = [0] * checked_instance.m
    for edge_ref, count in entries:
        dense[edge_ref] = count
    return tuple(dense)


def validate_witness(instance: Instance, witness: Witness) -> None:
    """Validate one compact witness against an exact production instance."""

    checked_instance = _require_instance(instance)
    if type(witness) is not Witness:
        raise ValueError("witness must be an exact Witness")

    checked_shore = validate_shore(checked_instance.n, witness.U)
    if checked_shore == 0:
        raise ValueError("a witness shore must be nonempty")
    _validate_dense(checked_instance, checked_shore, witness.y)

    total = shore_f(checked_instance, checked_shore) + sum(witness.y)
    if total % 2 == 0:
        raise ValueError("witness admissibility total must be odd")
    if total < 3:
        raise ValueError("witness admissibility total must be at least three")


def witness_value(instance: Instance, witness: Witness) -> ExactValue:
    """Return the literal raw value attained by one admissible compact witness."""

    checked_instance = _require_instance(instance)
    if type(witness) is not Witness:
        raise ValueError("witness must be an exact Witness")

    validate_witness(checked_instance, witness)
    selected = sum(witness.y)
    numerator = 2 * (shore_e_q(checked_instance, witness.U) + selected)
    denominator = shore_f(checked_instance, witness.U) + selected - 1
    return ExactValue(numerator, denominator)

